    if(effect.manaMeltdown==='strong')return <div className={`card-choice ${className}`}><span>{label} · choose a crystal color you own</span>{Object.entries(player.crystals).filter(([,count])=>count>0).map(([crystalColor,count])=><button className={crystalColor} key={crystalColor} onClick={()=>commit(mode,{crystalColor})}>{crystalColor} · {count} Wound{count===1?'':'s'}</button>)}</div>;
    if(effect.energyFlow){const setup=energyFlowSetup?.mode===mode?energyFlowSetup:{mode,unitId:null,opponentUnits:[]},selectedFor=playerId=>setup.opponentUnits.find(item=>item.playerId===playerId);return <div className={`card-choice ${className}`}><span>{label} · choose your spent Unit</span>{units.filter(unit=>unit.spent).map(unit=><button className={setup.unitId===unitKey(unit)?'selected':''} key={unitKey(unit)} onClick={()=>setEnergyFlowSetup({...setup,unitId:unitKey(unit)})}>{unit.name}{effect.energyFlow.heal&&unit.wounded?' · heal 1 Wound':''}</button>)}{players.filter(other=>other.id&&other.id!==player.id).map(other=><div key={other.id}><small>Optionally spend one of {other.name}'s Units</small>{other.units.filter(unit=>!unit.spent&&unit.level<=effect.energyFlow.opponentMaxLevel).map(unit=><button className={selectedFor(other.id)?.unitId===unitKey(unit)?'selected':''} key={unitKey(unit)} onClick={()=>setEnergyFlowSetup({...setup,opponentUnits:[...setup.opponentUnits.filter(item=>item.playerId!==other.id),...(selectedFor(other.id)?.unitId===unitKey(unit)?[]:[{playerId:other.id,unitId:unitKey(unit)}])]})}>{unit.name} · level {unit.level}</button>)}</div>)}<button className="primary" disabled={!setup.unitId} onClick={()=>{commit(mode,{unitId:setup.unitId,opponentUnits:setup.opponentUnits});setEnergyFlowSetup(null)}}>Commit energy flow</button></div>;}
    if(effect.callToArms==='borrow'){const colors=['blue','red','green','white'],pairs=colors.flatMap((first,index)=>colors.slice(index).map(second=>[first,second]));return <div className={`card-choice ${className}`}><span>{label} · borrow an offered Unit ability</span>{unitOffer.flatMap(unit=>legalUnitPowerOptions(unit,phase).filter(power=>!power.manaCost?.length).flatMap(power=>{const base={offerUnitId:unitKey(unit),abilityId:power.id};if(power.effect==='readyUnit')return units.filter(target=>target.spent&&!target.wounded&&(target.level||1)<=power.maxLevel).map(target=><button key={`${unitKey(unit)}-${power.id}-${unitKey(target)}`} onClick={()=>commit(mode,{...base,unitId:unitKey(target)})}>{unit.name} · {unitPowerLabel(power)} · {target.name}</button>);if(power.effect==='chooseMana')return pairs.map(colors=><button key={`${unitKey(unit)}-${power.id}-${colors.join('-')}`} onClick={()=>commit(mode,{...base,colors})}>{unit.name} · {colors.join(' + ')}</button>);if(['cancelAttack','freezeEnemy'].includes(power.effect))return enemies.map(enemy=><button key={`${unitKey(unit)}-${power.id}-${enemy.uid||enemy.id}`} onClick={()=>commit(mode,{...base,targetId:enemy.uid||enemy.id})}>{unit.name} · {unitPowerLabel(power)} · {enemy.name}</button>);return [<button key={`${unitKey(unit)}-${power.id}`} onClick={()=>commit(mode,base)}>{unit.name} · {unitPowerLabel(power)}</button>]}))}</div>;}
