    if(effect.pureMagic){const mapping={green:'move',white:'influence',blue:'block',red:'attack'},available=[...new Set(mana.filter(color=>['blue','red','green','white','gold'].includes(color)))],legal=color=>legalCardEffectTypes({[color]:1},phase).length;return <div className={`card-choice ${className}`}><span>{label} · spend a mana token</span>{available.flatMap(pureColor=>pureColor==='gold'?Object.values(mapping).filter(legal).map(effectAs=><button key={`gold-${effectAs}`} onClick={()=>commit(mode,{pureColor,effectAs})}>gold → {effectAs} +{effect.pureMagic}</button>):legal(mapping[pureColor])?[<button className={pureColor} key={pureColor} onClick={()=>commit(mode,{pureColor})}>{pureColor} → {mapping[pureColor]} +{effect.pureMagic}</button>]:[])}</div>;}
