    if(effect.training)return <div className={`card-choice ${className}`}><span>{label} · remove an Action and learn its color</span>{hand.filter(item=>item.uid!==card.uid&&item.id!=='wound'&&!['spell','artifact'].includes(item.type)).flatMap(item=>advancedOffer.filter(offered=>offered.color===item.color).map(offered=><button key={`${item.uid}-${offered.id}`} onClick={()=>commit(mode,{removeUid:item.uid,advancedId:offered.id})}>Remove {item.name} → {offered.name}</button>))}</div>;
    if(effect.manaStorm==='crystal-and-reroll')return <div className={`card-choice ${className}`}><span>{label} · choose Source die</span>{source.filter(die=>!die.claimedBy&&['blue','red','green','white'].includes(die.color)).map(die=><button className={die.color} key={die.id} onClick={()=>commit(mode,{dieId:die.id})}>{die.color} die</button>)}</div>;
    if(effect.bloodRitual){const count=effect.bloodRitual.tokens,setup=ritualSetup?.mode===mode?ritualSetup:{mode,manaColors:[],crystalColor:null},colors=['blue','red','green','white','gold','black'],crystallizable=[...new Set([...mana,...setup.manaColors].filter(color=>['blue','red','green','white'].includes(color)))];return <div className={`card-choice ${className}`}><span>{label} · choose {count} mana token color{count===1?'':'s'}</span><small>{setup.manaColors.join(' + ')||'none selected'}</small>{colors.map(color=><button className={color} disabled={setup.manaColors.length>=count} key={color} onClick={()=>setRitualSetup({...setup,manaColors:[...setup.manaColors,color],crystalColor:null})}>{color}</button>)}{setup.manaColors.length>0&&<button onClick={()=>setRitualSetup({...setup,manaColors:[],crystalColor:null})}>Reset</button>}{effect.bloodRitual.mayCrystallize&&crystallizable.map(color=><button className={setup.crystalColor===color?'selected':''} key={`crystal-${color}`} onClick={()=>setRitualSetup({...setup,crystalColor:setup.crystalColor===color?null:color})}>{setup.crystalColor===color?'✓ ':''}{color} → crystal</button>)}<button className="primary" disabled={setup.manaColors.length!==count} onClick={()=>{commit(mode,{manaColors:setup.manaColors,...(setup.crystalColor?{crystalColor:setup.crystalColor}:{})});setRitualSetup(null)}}>Commit ritual</button></div>;}
