    if(effect.bloodAncients==='basic')return <div className={`card-choice ${className}`}><span>{label} · choose acquisition</span><button onClick={()=>commit(mode)}>Take Wound only</button>{advancedOffer.map(offered=><button key={offered.id} onClick={()=>commit(mode,{advancedId:offered.id})}>Gain {offered.name}<small>pay {offered.color} mana</small></button>)}</div>;
    if(effect.bloodAncients==='powered')return <div className={`card-choice ${className}`}><span>{label} · choose Wound destination</span><button onClick={()=>commit(mode,{woundDestination:'hand'})}>Wound to hand</button><button onClick={()=>commit(mode,{woundDestination:'discard'})}>Wound to discard</button></div>;
