  const bowControls=role==='attack'&&duel.phase==='ranged'&&(card.basic?.bowDiscard||card.strong?.bowTransform)?<div className="card-choice discard-choice">{card.basic?.bowDiscard&&!siegeOnly&&<><span>Bow of Starsdawn · discard any non-Wound cards</span>{game.player.hand.filter(item=>item.uid!==card.uid&&item.id!=='wound').map(item=><button className={bowUids.includes(item.uid)?'selected':''} key={item.uid} onClick={()=>setBowUids(old=>old.includes(item.uid)?old.filter(uid=>uid!==item.uid):[...old,item.uid])}>{item.name}</button>)}<button onClick={()=>{dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'basic',discardUids:bowUids});setBowUids([])}}>Use basic · Ranged Attack {bowUids.length*2}</button></>}{card.strong?.bowTransform&&<button className="danger-action" onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'strong'})}>Throw away Bow<span>Transform every later Ranged/Siege contribution in this attack</span></button>}</div>:null;
  const circletControls=(card.basic?.circlet||card.strong?.circlet)?<div className="card-choice discard-choice">{card.basic?.circlet&&game.commonSkills.some(skill=>!skill.interactive&&legalPvpSkillModes(skill,duel.phase,role,effectiveSiegeOnly).length>0)&&<button onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'basic'})}>Use Circlet<span>Invoke a usable Common Skill</span></button>}{card.strong?.circlet&&game.commonSkills.some(skill=>!skill.interactive)&&<button className="danger-action" onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'strong'})}>Destroy Circlet<span>Permanently acquire a Common Skill</span></button>}</div>:null;
  const ringControls=(card.basic?.manaRing||card.strong?.manaRing)?<div className="card-choice discard-choice">{card.basic?.manaRing&&<button onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'basic'})}>Use {card.name}<span>{effectText(card.basic)}</span></button>}{card.strong?.manaRing&&<button className="danger-action" onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'strong'})}>Destroy {card.name}<span>{effectText(card.strong)}</span></button>}</div>:null;
  const gemControls=(card.basic?.gemPouch||card.strong?.gemPouch)?<div className="card-choice discard-choice">{card.basic?.gemPouch&&<button onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'basic'})}>Roll {card.name}<span>{effectText(card.basic)}</span></button>}{card.strong?.gemPouch&&<button className="danger-action" onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'strong'})}>Destroy {card.name}<span>{effectText(card.strong)}</span></button>}</div>:null;
  const sunControls=(card.basic?.sunAmulet||card.strong?.sunAmulet)?<div className="card-choice discard-choice">{card.basic?.sunAmulet&&<button onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'basic'})}>Use {card.name}<span>{effectText(card.basic)}</span></button>}{card.strong?.sunAmulet&&<button className="danger-action" onClick={()=>dispatch({type:'PVP_PLAY_CARD',uid:card.uid,mode:'strong'})}>Destroy {card.name}<span>{effectText(card.strong)}</span></button>}</div>:null;
