    {duel.stage==='block'&&amCurrent&&<button className="primary" onClick={()=>dispatch({type:'PVP_RESOLVE_BLOCK'})}>Resolve Block {duel.blockPower}<span>{duel.phase==='ranged'?'Every 2 efficient Block cancels 1 Attack':'Every Block cancels 1 Attack'}</span></button>}
